Write-Host "Modifications appliquees avec succes !" -ForegroundColor Green
Write-Host "Tu peux maintenant changer le statut de paiement (en attente / partiel / paye / rembourse) directement dans Commandes / Ventes." -ForegroundColor Green
Write-Host "La Comptabilite affiche desormais l'argent REELLEMENT encaisse, pas juste les commandes passees." -ForegroundColor Green
Write-Host ""
$confirm = Read-Host "Voulez-vous faire git add / commit / push maintenant ? (o/n)"
if ($confirm -eq 'o' -or $confirm -eq 'O') {
    git add lib/actions/orders.ts components/admin/payment-status-select.tsx components/admin/order-row.tsx app/admin/comptabilite/page.tsx
    git commit -m "Feat: suivi du statut de paiement des commandes, synchronise avec la comptabilite (CA encaisse vs facture)"
    git push
    Write-Host "Pousse sur Git avec succes !" -ForegroundColor Green
} else {
    Write-Host "Pas de push. Vous pouvez le faire plus tard avec : git add . ; git commit -m '...' ; git push" -ForegroundColor Yellow
}
